func (this *Bullish) HandleBalance(client any, message any) {
	//
	// snapshot
	//     {
	//         "type": "snapshot",
	//         "tradingAccountId": "111309424211255",
	//         "dataType": "V1TAAssetAccount",
	//         "data": [
	//             {
	//                 "updatedAtTimestamp": "1751989627509",
	//                 "borrowedQuantity": "0.0000",
	//                 "tradingAccountId": "111309424211255",
	//                 "loanedQuantity": "0.0000",
	//                 "lockedQuantity": "0.0000",
	//                 "assetId": "5",
	//                 "assetSymbol": "USDC",
	//                 "publishedAtTimestamp": "1751989627512",
	//                 "availableQuantity": "999672939.8767",
	//                 "updatedAtDatetime": "2025-07-08T15:47:07.509Z"
	//             }
	//         ]
	//     }
	//
	// update
	//     {
	//         "type": "update",
	//         "tradingAccountId": "111309424211255",
	//         "dataType": "V1TAAssetAccount",
	//         "data": {
	//             "updatedAtTimestamp": "1751989627509",
	//             "borrowedQuantity": "0.0000",
	//             "tradingAccountId": "111309424211255",
	//             "loanedQuantity": "0.0000",
	//             "lockedQuantity": "0.0000",
	//             "assetId": "5",
	//             "assetSymbol": "USDC",
	//             "publishedAtTimestamp": "1751989627512",
	//             "availableQuantity": "999672939.8767",
	//             "updatedAtDatetime": "2025-07-08T15:47:07.509Z"
	//         }
	//     }
	//
	var tradingAccountId *string = this.SafeString(message, "tradingAccountId")
	if tradingAccountId == nil {
		return
	}
	if !(ccxt.InOp(this.Balance, tradingAccountId)) {
		ccxt.AddElementToObject(this.Balance, tradingAccountId, map[string]any{})
	}
	var messageType *string = this.SafeString(message, "type")
	if messageType != nil && *messageType == "snapshot" {
		var data []any = ccxt.SafeListTypedDefault(message, "data", []any{})
		var parsed any = this.ParseBalance(data)
		var parsedKeys []string = ccxt.ObjectKeys(parsed)
		for i := 0; i < len(parsedKeys); i++ {
			var parsedKey string = parsedKeys[i]
			ccxt.AddElementToObject(ccxt.GetValue(this.Balance, tradingAccountId), parsedKey, ccxt.GetValue(parsed, parsedKey))
		}
		ccxt.AddElementToObject(this.Balance, tradingAccountId, this.SafeBalance(ccxt.GetValue(this.Balance, tradingAccountId)))
	} else {
		var data map[string]any = ccxt.SafeMapTyped(message, "data")
		var assetId *string = this.SafeString(data, "assetSymbol")
		var account map[string]any = this.Account()
		account["total"] = this.SafeString(data, "availableQuantity")
		account["used"] = this.SafeString(data, "lockedQuantity")
		var code *string = this.SafeCurrencyCode(assetId)
		if (tradingAccountId != nil) && (code != nil) {
			ccxt.AddElementToObject(ccxt.GetValue(this.Balance, tradingAccountId), code, account)
		}
		ccxt.AddElementToObject(ccxt.GetValue(this.Balance, tradingAccountId), "info", message)
		ccxt.AddElementToObject(this.Balance, tradingAccountId, this.SafeBalance(ccxt.GetValue(this.Balance, tradingAccountId)))
	}
	var messageHash string = "balance"
	var tradingAccountIdHash string = "::" + *tradingAccountId
	client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(this.Balance, tradingAccountId), messageHash)
	client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(this.Balance, tradingAccountId), messageHash+tradingAccountIdHash)
}

/**
 * @method
 * @name bullish#watchPositions
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#overview--private-data-websocket-authenticated
 * @description watch all open positions
 * @param {string[]} [symbols] list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Bullish) WatchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) watchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var subscribeHash string = "positions"
	var messageHash string = subscribeHash
	var hasSymbols bool = (symbols != nil) && !this.IsEmpty(symbols)
	var symbolsNormalized any = symbols
	if hasSymbols {
		symbolsNormalized = this.MarketSymbols(symbols)
	}
	if hasSymbols && (!ccxt.IsEqual(symbolsNormalized, nil)) {
		messageHash += "::" + ccxt.Join(symbolsNormalized, ",")
	}
	var request map[string]any = map[string]any{
		"topic": "derivativesPositionsV2",
	}

	positions := (<-this.WatchPrivateAsync(messageHash, subscribeHash, request, params))
	ccxt.PanicOnError(positions)
	if this.NewUpdates {

		ch <- positions
		return nil
	}

	ch <- this.FilterBySymbolsSinceLimit(positions, symbolsNormalized, since, limit, true)
	return nil
}
func (this *Bullish) HandlePositions(client any, message map[string]any) {
	// exchange does not return messages for sandbox mode
	// current method is implemented blindly
	// todo: check if this works with not-sandbox mode
	var messageType *string = this.SafeString(message, "type")
	var rawPositions []any = []any{}
	if messageType != nil && *messageType == "update" {
		var data map[string]any = this.SafeDictMap(message, "data", map[string]any{})
		rawPositions = append(rawPositions, data)
	} else {
		rawPositions = ccxt.ArrayTyped(this.SafeList(message, "data", []any{}))
	}
	if this.Positions == nil {
		this.Positions = ccxt.NewArrayCacheBySymbolBySide()
	}
	var positions any = this.Positions
	var newPositions []any = []any{}
	for i := 0; i < len(rawPositions); i++ {
		var rawPosition any = func() any {
			if i >= 0 && i < len(rawPositions) {
				return ccxt.DerefScalar(rawPositions[i])
			}
			return nil
		}()
		var position map[string]any = ccxt.MapTyped(this.ParsePosition(rawPosition))
		positions.(ccxt.Appender).Append(position)
		newPositions = append(newPositions, position)
	}
	var messageHashes []any = ccxt.ArrayTyped(this.FindMessageHashes(ccxt.AsClient(client), "positions::"))
	for i := 0; i < len(messageHashes); i++ {
		var messageHash *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(messageHashes) {
				return ccxt.DerefScalar(messageHashes[i])
			}
			return nil
		}())
		var parts []string = strings.Split(*messageHash, "::")
		var symbolsString *string = ccxt.SafeStringPtr(ccxt.GetValue(parts, 1))
		var symbols []string = strings.Split(*symbolsString, ",")
		var symbolPositions any = this.FilterByArray(newPositions, "symbol", symbols, false)
		if !this.IsEmpty(symbolPositions) {
			client.(ccxt.ClientInterface).Resolve(symbolPositions, messageHash)
		}
	}
	client.(ccxt.ClientInterface).Resolve(positions, "positions")
}
func (this *Bullish) HandleErrorMessage(client any, message any) {
	//
	//     {
	//         "data": {
	//             "errorCode": 401,
	//             "errorCodeName": "UNAUTHORIZED",
	//             "message": "Unable to authenticate; JWT is missing/invalid or unauthorised to access account"
	//         },
	//         "dataType": "V1TAErrorResponse",
	//         "type": "error"
	//     }
	//
	var data map[string]any = this.SafeDictMap(message, "data", map[string]any{})
	var feedback string = this.Id + " " + this.Json(data)

	{
		func(this *Bullish) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Bullish) any {
						// catch block:
						client.(ccxt.ClientInterface).Reject(e)
						return nil
					}(this)
				}
			}()
			// try block:
			var errorCode *string = this.SafeString(data, "errorCode")
			var errorCodeName *string = this.SafeString(data, "errorCodeName")
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errorCodeName, feedback)
			panic(ccxt.ExchangeError(feedback))

		}(this)

	}
}
func (this *Bullish) HandleMessage(client any, message any) {
	var dataType *string = this.SafeString(message, "dataType")
	var result map[string]any = ccxt.SafeMapTyped(message, "result")
	if result != nil {
		var response *string = this.SafeString(result, "message")
		if response != nil && *response == "Keep alive pong" {
			this.HandlePong(client, message)
		}
	} else if dataType != nil {
		if dataType != nil && *dataType == "V1TAAnonymousTradeUpdate" {
			this.HandleTrades(client, message)
		}
		if dataType != nil && *dataType == "V1TATickerResponse" {
			this.HandleTicker(client, message)
		}
		if dataType != nil && *dataType == "V1TALevel2" {
			this.HandleOrderBook(client, message)
		}
		if dataType != nil && *dataType == "V1TAOrder" {
			this.HandleOrders(client, message)
		}
		if dataType != nil && *dataType == "V1TATrade" {
			this.HandleMyTrades(client, message)
		}
		if dataType != nil && *dataType == "V1TAAssetAccount" {
			this.HandleBalance(client, message)
		}
		if dataType != nil && *dataType == "V1TAErrorResponse" {
			this.HandleErrorMessage(client, message)
		}
	}
}

