func (this *Bullish) WatchMyTrades(options ...ccxt.WatchMyTradesOptions) ([]ccxt.Trade, error) {

	opts := ccxt.WatchMyTradesOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}
	raw := <-this.WatchMyTradesAsync(opts.Symbol, opts.Since, opts.Limit, opts.Params)
	if ccxt.IsError(raw) {
		return nil, ccxt.CreateReturnError(raw)
	}
	var res []ccxt.Trade = ccxt.NewTradeArray(raw)
	return res, nil
}

/**
 * @method
 * @name bullish#watchBalance
 * @description watch balance and get the amount of funds available for trading or funds locked in orders
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#overview--private-data-websocket-authenticated
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tradingAccountId] the trading account id to fetch entries for
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Bullish) WatchBalance(params ...any) (ccxt.Balances, error) {
	raw := <-this.WatchBalanceAsync(params...)
	if ccxt.IsError(raw) {
		return ccxt.Balances{}, ccxt.CreateReturnError(raw)
	}
	var res ccxt.Balances = ccxt.NewBalances(raw)
	return res, nil
}

/**
 * @method
 * @name bullish#watchPositions
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#overview--private-data-websocket-authenticated
 * @description watch all open positions
 * @param {string[]} [symbols] list of unified market symbols
 * @param {int} [since] the earliest time in ms to fetch positions for
 * @param {int} [limit] the maximum number of positions to retrieve
 * @param {object} params extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
 */
func (this *Bullish) WatchPositions(options ...ccxt.WatchPositionsOptions) ([]ccxt.Position, error) {

	opts := ccxt.WatchPositionsOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}
	raw := <-this.WatchPositionsAsync(opts.Symbols, opts.Since, opts.Limit, opts.Params)
	if ccxt.IsError(raw) {
		return nil, ccxt.CreateReturnError(raw)
	}
	var res []ccxt.Position = ccxt.NewPositionArray(raw)
	return res, nil
}
